@APP.get("/api/v3/alerts/smart_cap")
async def api_v3_alerts_smart_cap():
    """
    Get Smart Cap status - daily alert limiting system.
    
    SMART CAP prevents spam by:
    - Limiting to 10 alerts per day (configurable)
    - Requiring 80%+ confidence minimum
    - Last 3 slots need 85%+ confidence
    - Last slot needs 90%+ confidence
    
    Returns current count, cap, and today's alerts log.
    """
    try:
        from core.telegram_alerts import (
            get_daily_alert_count, 
            get_daily_alert_log, 
            DAILY_ALERT_CAP,
            MIN_ALERT_CONFIDENCE,
            SMART_CAP_ENABLED
        )
        
        count = get_daily_alert_count()
        log = get_daily_alert_log()
        remaining = DAILY_ALERT_CAP - count
        
        # Determine current minimum required confidence
        if remaining <= 1:
            current_min = 0.90
        elif remaining <= 3:
            current_min = 0.85
        else:
            current_min = MIN_ALERT_CONFIDENCE
        
        return {
            "ok": True,
            "smart_cap_enabled": SMART_CAP_ENABLED,
            "daily_cap": DAILY_ALERT_CAP,
            "alerts_sent_today": count,
            "alerts_remaining": remaining,
            "min_confidence_base": MIN_ALERT_CONFIDENCE,
            "min_confidence_current": current_min,
            "alerts_log": log,
            "next_slot_requirement": (
                f"90%+ (last slot)" if remaining == 1 else
                f"85%+ (high conviction only)" if remaining <= 3 else
                f"{MIN_ALERT_CONFIDENCE:.0%}+ (standard)"
            ),
            "status": "capped" if remaining <= 0 else "accepting",
            "timestamp": time.time()
        }
    
    except Exception as e:
        LOGGER.error(f"Smart cap status failed: {e}", exc_info=True)
        return {
            "ok": False,
            "error": str(e)
        }


@APP.get("/api/v3/accuracy/real")
async def api_v3_accuracy_real():
    """
    Get REAL verified accuracy stats - not hardcoded lies.
    
    Returns:
    - verified_predictions: Number of predictions with known outcomes
    - wins: Successful predictions
    - losses: Failed predictions  
    - accuracy_pct: REAL accuracy percentage
    - avg_return: Average actual return
    
    This is the source of truth for system accuracy.
    """
    try:
        from core.prediction_store import get_prediction_store
        
        store = get_prediction_store()
        
        # Get stats for different periods
        all_time = store.get_accuracy_stats('all_time') if hasattr(store, 'get_accuracy_stats') else {}
        last_7d = store.get_accuracy_stats('last_7_days') if hasattr(store, 'get_accuracy_stats') else {}
        last_30d = store.get_accuracy_stats('last_30_days') if hasattr(store, 'get_accuracy_stats') else {}
        
        # If the store doesn't have get_accuracy_stats, compute from predictions
        if not all_time:
            preds = store.list_predictions(limit=1000) if hasattr(store, 'list_predictions') else []
            verified = [p for p in preds if p.get('hit_direction') is not None]
            wins = sum(1 for p in verified if p.get('hit_direction') == True)
            losses = sum(1 for p in verified if p.get('hit_direction') == False)
            total = len(verified)
            accuracy = (wins / (wins + losses) * 100) if (wins + losses) > 0 else 0
            
            all_time = {
                'period': 'all_time',
                'total_predictions': len(preds),
                'verified_predictions': total,
                'wins': wins,
                'losses': losses,
                'accuracy_pct': round(accuracy, 1),
                'avg_return': 0
            }
        
        return {
            "ok": True,
            "all_time": all_time,
            "last_7_days": last_7d,
            "last_30_days": last_30d,
            "note": "This is REAL verified accuracy, not hardcoded",
            "timestamp": time.time()
        }
        
    except Exception as e:
        LOGGER.error(f"Real accuracy fetch failed: {e}", exc_info=True)
        return {
            "ok": False,
            "error": str(e),
            "all_time": {
                "verified_predictions": 0,
                "wins": 0,
                "losses": 0,
                "accuracy_pct": 0,
                "note": "Error fetching stats"
            }
        }


