@APP.get("/api/v3/live_recalculator/status")
async def api_v3_live_recalculator_status(limit_snapshots: int = 50, limit_signals: int = 50):
    """Get latest live recalculator snapshots and exit signals.

    Reads from `data/live_recalculator.db` written by `core.live_recalculator`.

    Args:
        limit_snapshots: Max number of snapshot rows to return (default 50)
        limit_signals: Max number of exit signal rows to return (default 50)
    """
    try:
        import sqlite3
        from pathlib import Path

        db_path = Path(__file__).parent / "data" / "live_recalculator.db"

        if not db_path.exists():
            return {
                "ok": False,
                "enabled": False,
                "error": "live_recalculator.db not found",
                "db_path": str(db_path),
                "latest_ts": 0,
                "snapshots": [],
                "exit_signals": [],
            }

        conn = sqlite3.connect(str(db_path))
        cur = conn.cursor()

        # Detect tables
        cur.execute("SELECT name FROM sqlite_master WHERE type='table'")
        tables = {r[0] for r in (cur.fetchall() or [])}

        snapshots: list[dict] = []
        signals: list[dict] = []
        latest_ts = 0

        if "position_snapshots" in tables:
            cur.execute(
                """
                SELECT ts, symbol, qty, avg_entry_price, current_price, unrealized_pl, unrealized_plpc
                FROM position_snapshots
                ORDER BY ts DESC, id DESC
                LIMIT ?
                """,
                (max(1, min(int(limit_snapshots), 500)),),
            )
            rows = cur.fetchall() or []
            for (ts, symbol, qty, avg_entry, current_price, upl, uplpc) in rows:
                latest_ts = max(latest_ts, int(ts or 0))
                snapshots.append(
                    {
                        "ts": int(ts or 0),
                        "symbol": symbol,
                        "qty": qty,
                        "avg_entry_price": avg_entry,
                        "current_price": current_price,
                        "unrealized_pl": upl,
                        "unrealized_plpc": uplpc,
                    }
                )

        if "exit_signals" in tables:
            cur.execute(
                """
                SELECT ts, symbol, type, reason, pnl_pct, entry_price, current_price
                FROM exit_signals
                ORDER BY ts DESC, id DESC
                LIMIT ?
                """,
                (max(1, min(int(limit_signals), 500)),),
            )
            rows = cur.fetchall() or []
            for (ts, symbol, typ, reason, pnl_pct, entry_price, current_price) in rows:
                latest_ts = max(latest_ts, int(ts or 0))
                signals.append(
                    {
                        "ts": int(ts or 0),
                        "symbol": symbol,
                        "type": typ,
                        "reason": reason,
                        "pnl_pct": pnl_pct,
                        "entry_price": entry_price,
                        "current_price": current_price,
                    }
                )

        conn.close()

        return {
            "ok": True,
            "enabled": True,
            "db_path": str(db_path),
            "tables": sorted(list(tables)),
            "latest_ts": latest_ts,
            "snapshots": snapshots,
            "exit_signals": signals,
        }

    except Exception as e:
        LOGGER.error(f"Live recalculator status failed: {e}", exc_info=True)
        return {
            "ok": False,
            "enabled": False,
            "error": str(e),
            "latest_ts": 0,
            "snapshots": [],
            "exit_signals": [],
        }


@APP.get("/api/v3/health/metrics")
async def api_v3_health_metrics():
    """
    Calculate real-time health metrics for the cockpit.
    
    Returns:
        - data_health: Provider uptime (test BTC availability)
        - ai_activity: Predictions per hour
        - accuracy: Win rate from V2-filtered paper trades
        - cache_performance: Price cache hit rate
    """
    try:
        # V2 ERA: Start date for clean data
        V2_START_DATE = "2026-01-14"
        
        # Data Health: Check if crypto providers are working
        data_health = 50  # Default if provider unavailable
        try:
            # Use quorum price which is more reliable and returns 24h change
            from core.crypto.crypto_providers import get_crypto_price_quorum, get_cache_stats
            
            # Try to get price for a V2 whitelisted crypto
            chz_data = await get_crypto_price_quorum("CHZ", use_cache=True)
            
            if chz_data and chz_data.get("price", 0) > 0:
                # Check quorum quality
                quorum_size = chz_data.get("quorum_size", 1)
                if quorum_size >= 2:
                    data_health = 95  # Strong quorum
                else:
                    data_health = 80  # Single provider working
            else:
                # Fallback: check cache stats
                try:
                    cache_stats = get_cache_stats()
                    hit_rate = cache_stats.get("hit_rate_pct", 0)
                    cache_size = cache_stats.get("cache_size", 0)
                    if cache_size > 0 and hit_rate > 30:
                        data_health = 70  # Cache working
                    elif cache_size > 0:
                        data_health = 60  # Cache has data
                    else:
                        data_health = 40  # No cache data
                except Exception:
                    data_health = 40
        except Exception as e:
            LOGGER.warning(f"Health check provider test failed: {e}")
            data_health = 50  # Unknown state
        
        # AI Activity: Count recent predictions (predictions per hour)
        # BUG 4 FIX: Also check paper trades as activity indicator
        total_predictions = len(_LATEST_PREDICTIONS)
        try:
            from core.paper_tracker import get_paper_tracker
            tracker = get_paper_tracker()
            paper_stats = tracker.get_stats(days=1)
            pending_trades = paper_stats.get("pending_trades", 0)
            total_predictions = max(total_predictions, pending_trades)
        except Exception:
            pass
        
        # More generous activity thresholds
        if total_predictions >= 50:
            ai_activity = 90
        elif total_predictions >= 20:
            ai_activity = 75
        elif total_predictions >= 10:
            ai_activity = 60
        elif total_predictions >= 5:
            ai_activity = 50
        else:
            ai_activity = 40  # Minimum activity (system is running)
        
        # Accuracy: Calculate from V2-filtered paper trades (not _PREDICTION_STORE)
        accuracy = 50  # Default
        try:
            from core.paper_tracker import get_paper_tracker
            tracker = get_paper_tracker()
            stats = tracker.get_stats(since=V2_START_DATE, v2_only=True)
            if stats.get("resolved_trades", 0) > 0:
                accuracy = round(stats.get("win_rate_pct", 50), 1)
        except Exception:
            pass
        
        # Cache Performance: Get price cache statistics
        cache_stats = {}
        try:
            from core.crypto.crypto_providers import get_cache_stats
            cache_stats = get_cache_stats()
        except Exception:
            pass
        
        return {
            "ok": True,
            "data_health": data_health,
            "ai_activity": ai_activity,
            "accuracy": accuracy,
            "cache_performance": cache_stats,
            "v2_start_date": V2_START_DATE,
            "timestamp": datetime.now(UTC).isoformat()
        }
    
    except Exception as e:
        LOGGER.error(f"Health metrics failed: {e}", exc_info=True)
        return {
            "ok": False,
            "data_health": 50,
            "ai_activity": 50,
            "accuracy": 50,
            "error": str(e)
        }


