@APP.get("/api/agentkit/chat")
async def api_agentkit_chat(
    message: str,
    conversation_id: str | None = None,
    credentials: HTTPAuthorizationCredentials | None = AUTH_DEP,
):
    """
    AgentKit - Natural language AI conversations
    
    Stateful persistent conversations using OpenAI Assistants API.
    
    Features:
    - Multi-turn conversations with memory
    - Tool calling (get_price, get_news, get_position, dispatch_alert)
    - Natural language understanding
    - Cost: $0.01-$0.10 per conversation
    
    Args:
        message: Your question or command
        conversation_id: Optional conversation ID for follow-ups
    
    Returns:
        - response: AI response text
        - conversation_id: ID for follow-up messages
        - tools_used: List of tools called during conversation
    """
    try:
        _require_bearer(
            (f"Bearer {credentials.credentials}")
            if credentials and credentials.credentials
            else None
        )
    except Exception:
        pass
    
    if os.getenv("AGENTKIT_ENABLED", "0") != "1":
        raise HTTPException(503, "AgentKit not enabled. Set AGENTKIT_ENABLED=1")
    
    if not os.getenv("OPENAI_AGENT_API_KEY"):
        raise HTTPException(503, "AgentKit requires OPENAI_AGENT_API_KEY")
    
    try:
        from llm.agentkit import get_agentkit_client
        
        client = get_agentkit_client()
        
        result = await client.chat(
            message=message,
            conversation_id=conversation_id
        )
        
        return {
            "message": message,
            "response": result["response"],
            "conversation_id": result["conversation_id"],
            "tools_used": result.get("tools_used", []),
            "timestamp": int(time.time()),
        }
    
    except HTTPException:
        raise
    except Exception as e:
        LOGGER.error(f"AgentKit chat failed: {e}", exc_info=True)
        raise HTTPException(500, f"Chat failed: {str(e)[:200]}")


def _get_pooled_session_for(url: str) -> requests.Session:
    host = _get_host(url)
    s = _HTTP_SESSIONS.get(host)
    if s is not None:
        return s
    s = requests.Session()
    # Ban very large pools; use HTTPAdapter with limited pools and retries
    if Retry is not None:
        retry = Retry(
            total=HTTP_POOL_RETRIES,
            backoff_factor=0.3,
            status_forcelist=(429, 500, 502, 503, 504),
            allowed_methods=("GET", "POST"),
            raise_on_status=False,
        )
    else:
        retry = None  # type: ignore
    adapter = HTTPAdapter(
        pool_connections=HTTP_POOL_SIZE,
        pool_maxsize=HTTP_POOL_SIZE,
        max_retries=(retry or 0),
    )
    s.mount("http://", adapter)
    s.mount("https://", adapter)
    _HTTP_SESSIONS[host] = s
    return s


def _http_get(
    url: str, *, timeout: float | None = None, headers: dict[str, str] | None = None
) -> requests.Response:
    t = timeout or HTTP_TIMEOUT_S
    try:
        if HTTP_POOL_ENABLED:
            sess = _get_pooled_session_for(url)
            if _C_HTTP_POOL_USED is not None:
                try:
                    _C_HTTP_POOL_USED.labels(host=_get_host(url)).inc()
                except Exception:
                    pass
            return sess.get(url, timeout=t, headers=headers or {})
        else:
            if _C_HTTP_DIRECT_USED is not None:
                try:
                    _C_HTTP_DIRECT_USED.labels(host=_get_host(url)).inc()
                except Exception:
                    pass
            return requests.get(url, timeout=t, headers=headers or {})
    except Exception:
        # Bubble up to callers
        raise


def _http_post(
    url: str,
    *,
    json: Any | None = None,
    data: Any | None = None,
    timeout: float | None = None,
    headers: dict[str, str] | None = None,
) -> requests.Response:
    t = timeout or HTTP_TIMEOUT_S
    try:
        if HTTP_POOL_ENABLED:
            sess = _get_pooled_session_for(url)
            if _C_HTTP_POOL_USED is not None:
                try:
                    _C_HTTP_POOL_USED.labels(host=_get_host(url)).inc()
                except Exception:
                    pass
            return sess.post(url, json=json, data=data, timeout=t, headers=headers or {})
        else:
            if _C_HTTP_DIRECT_USED is not None:
                try:
                    _C_HTTP_DIRECT_USED.labels(host=_get_host(url)).inc()
                except Exception:
                    pass
            return requests.post(url, json=json, data=data, timeout=t, headers=headers or {})
    except Exception:
        raise


