@APP.post("/debug/watchlist-add")
async def debug_watchlist_add(symbol: str = "", asset_type: str = "stock", secret: str = ""):
    """
    Debug endpoint to add symbols directly to watchlist.
    Bypasses API layer for testing.
    """
    if secret != os.getenv("CRON_SECRET", ""):
        return {"error": "Invalid secret"}
    
    if not symbol:
        return {"error": "symbol required"}
    
    try:
        import psycopg2
        
        database_url = os.getenv("DATABASE_URL")
        if not database_url:
            return {"ok": False, "error": "DATABASE_URL not set"}
        
        conn = psycopg2.connect(database_url)
        cursor = conn.cursor()
        
        symbol = symbol.upper().strip()
        asset_type = asset_type.lower().strip()
        
        # Check if exists
        cursor.execute("""
            SELECT id, active FROM ghost_watchlist_items 
            WHERE symbol = %s AND asset_type = %s
        """, (symbol, asset_type))
        existing = cursor.fetchone()
        
        if existing:
            item_id, was_active = existing
            cursor.execute("""
                UPDATE ghost_watchlist_items
                SET active = TRUE, updated_at = NOW()
                WHERE id = %s
            """, (item_id,))
            conn.commit()
            action = "re-activated" if not was_active else "updated"
        else:
            cursor.execute("""
                INSERT INTO ghost_watchlist_items (symbol, asset_type, owns_position, notes)
                VALUES (%s, %s, FALSE, '')
                RETURNING id
            """, (symbol, asset_type))
            item_id = cursor.fetchone()[0]
            conn.commit()
            action = "added"
        
        conn.close()
        return {"ok": True, "action": action, "symbol": symbol, "asset_type": asset_type, "id": item_id}
        
    except Exception as e:
        import traceback
        return {"ok": False, "error": str(e), "traceback": traceback.format_exc()}


@APP.post("/debug/watchlist-bulk-add")
async def debug_watchlist_bulk_add(request: Request, secret: str = ""):
    """
    Bulk add symbols to watchlist.
    Body: {"symbols": ["AAPL", "AMD", ...], "asset_type": "stock"}
    """
    if secret != os.getenv("CRON_SECRET", ""):
        return {"error": "Invalid secret"}
    
    try:
        import psycopg2
        
        body = await request.json()
        symbols = body.get("symbols", [])
        asset_type = body.get("asset_type", "stock").lower().strip()
        
        if not symbols:
            return {"error": "symbols list required"}
        
        database_url = os.getenv("DATABASE_URL")
        if not database_url:
            return {"ok": False, "error": "DATABASE_URL not set"}
        
        conn = psycopg2.connect(database_url)
        cursor = conn.cursor()
        
        added = []
        updated = []
        errors = []
        
        for symbol in symbols:
            try:
                symbol = symbol.upper().strip()
                
                cursor.execute("""
                    SELECT id, active FROM ghost_watchlist_items 
                    WHERE symbol = %s AND asset_type = %s
                """, (symbol, asset_type))
                existing = cursor.fetchone()
                
                if existing:
                    item_id, was_active = existing
                    cursor.execute("""
                        UPDATE ghost_watchlist_items
                        SET active = TRUE, updated_at = NOW()
                        WHERE id = %s
                    """, (item_id,))
                    if was_active:
                        updated.append(symbol)
                    else:
                        added.append(symbol)
                else:
                    cursor.execute("""
                        INSERT INTO ghost_watchlist_items (symbol, asset_type, owns_position, notes)
                        VALUES (%s, %s, FALSE, '')
                    """, (symbol, asset_type))
                    added.append(symbol)
            except Exception as e:
                errors.append(f"{symbol}: {e}")
        
        conn.commit()
        conn.close()
        
        return {
            "ok": True,
            "added": added,
            "updated": updated,
            "errors": errors,
            "total_added": len(added),
            "total_updated": len(updated)
        }
        
    except Exception as e:
        import traceback
        return {"ok": False, "error": str(e), "traceback": traceback.format_exc()}


@APP.get("/debug/watchlist-schema")
async def debug_watchlist_schema(secret: str = ""):
    """
    Check if ghost_watchlist_items table exists and show schema.
    Also create it if it doesn't exist.
    """
    if secret != os.getenv("CRON_SECRET", ""):
        return {"error": "Invalid secret"}
    
    try:
        import psycopg2
        
        database_url = os.getenv("DATABASE_URL")
        if not database_url:
            return {"ok": False, "error": "DATABASE_URL not set"}
        
        conn = psycopg2.connect(database_url)
        cursor = conn.cursor()
        
        # Check if table exists
        cursor.execute("""
            SELECT EXISTS (
                SELECT FROM information_schema.tables 
                WHERE table_name = 'ghost_watchlist_items'
            )
        """)
        exists = cursor.fetchone()[0]
        
        if not exists:
            # Create the table
            cursor.execute("""
                CREATE TABLE IF NOT EXISTS ghost_watchlist_items (
                    id BIGSERIAL PRIMARY KEY,
                    symbol TEXT NOT NULL,
                    asset_type TEXT NOT NULL CHECK (asset_type IN ('crypto', 'stock')),
                    owns_position BOOLEAN DEFAULT FALSE,
                    notes TEXT DEFAULT '',
                    added_at TIMESTAMPTZ DEFAULT NOW(),
                    updated_at TIMESTAMPTZ DEFAULT NOW(),
                    active BOOLEAN DEFAULT TRUE,
                    price_at_add REAL,
                    alert_threshold_pct REAL DEFAULT 5.0,
                    priority INTEGER DEFAULT 1,
                    CHECK (LENGTH(symbol) > 0 AND LENGTH(symbol) <= 20)
                )
            """)
            cursor.execute("""
                CREATE UNIQUE INDEX IF NOT EXISTS idx_watchlist_unique_active 
                ON ghost_watchlist_items(symbol, asset_type) WHERE active = TRUE
            """)
            cursor.execute("""
                CREATE INDEX IF NOT EXISTS idx_watchlist_symbol 
                ON ghost_watchlist_items(symbol) WHERE active = TRUE
            """)
            cursor.execute("""
                CREATE INDEX IF NOT EXISTS idx_watchlist_asset_type 
                ON ghost_watchlist_items(asset_type) WHERE active = TRUE
            """)
            conn.commit()
            
            conn.close()
            return {
                "ok": True,
                "created": True,
                "message": "ghost_watchlist_items table created successfully!"
            }
        
        # Get current count
        cursor.execute("SELECT COUNT(*) FROM ghost_watchlist_items WHERE active = TRUE")
        active_count = cursor.fetchone()[0]
        
        # Get breakdown
        cursor.execute("""
            SELECT asset_type, COUNT(*) as cnt 
            FROM ghost_watchlist_items 
            WHERE active = TRUE 
            GROUP BY asset_type
        """)
        breakdown = dict(cursor.fetchall())
        
        conn.close()
        
        return {
            "ok": True,
            "table_exists": True,
            "active_items": active_count,
            "breakdown": breakdown
        }
        
    except Exception as e:
        import traceback
        return {"ok": False, "error": str(e), "traceback": traceback.format_exc()}


@APP.get("/debug/learning-status")
async def debug_learning_status():
    """
    Check the status of Ghost's learning system.
    
    Shows:
    - Feedback loop status (feature weights, signal performance)
    - Learning loop status (parameter adjustments)
    - Recent outcomes processed
    - PostgreSQL vs SQLite outcome counts
    """
    try:
        from core.feedback_loop import get_feedback_loop
        from core.learning_loop import get_learning_loop
        import psycopg2
        import sqlite3
        
        feedback = get_feedback_loop()
        learning = get_learning_loop()
        
        # Get feedback loop report
        feedback_report = feedback.get_performance_report(days=7)
        
        # Get PostgreSQL outcome counts
        postgres_stats = {"total": 0, "wins": 0, "losses": 0, "accuracy_pct": 0}
        try:
            database_url = os.getenv("DATABASE_URL")
            if database_url:
                conn = psycopg2.connect(database_url)
                cursor = conn.cursor()
                # Don't filter by status - just count all outcomes
                cursor.execute("""
                    SELECT 
                        COUNT(*) as total,
                        SUM(CASE WHEN hit_direction = 1 THEN 1 ELSE 0 END) as wins,
                        SUM(CASE WHEN hit_direction = 0 THEN 1 ELSE 0 END) as losses
                    FROM ghost_prediction_outcomes
                """)
                row = cursor.fetchone()
                if row:
                    postgres_stats["total"] = row[0] or 0
                    postgres_stats["wins"] = row[1] or 0
                    postgres_stats["losses"] = row[2] or 0
                    if postgres_stats["total"] > 0:
                        postgres_stats["accuracy_pct"] = (postgres_stats["wins"] / postgres_stats["total"]) * 100
                conn.close()
        except Exception as pg_err:
            postgres_stats["error"] = str(pg_err)
        
        # Get SQLite feedback_loop.db counts
        sqlite_stats = {"total": 0, "wins": 0, "losses": 0}
        try:
            from pathlib import Path
            sqlite_path = Path(__file__).parent / "data" / "feedback_loop.db"
            if sqlite_path.exists():
                conn = sqlite3.connect(str(sqlite_path))
                cursor = conn.cursor()
                cursor.execute("""
                    SELECT 
                        COUNT(*) as total,
                        SUM(was_correct) as wins
                    FROM prediction_outcomes
                """)
                row = cursor.fetchone()
                if row:
                    sqlite_stats["total"] = row[0] or 0
                    sqlite_stats["wins"] = row[1] or 0
                    sqlite_stats["losses"] = sqlite_stats["total"] - sqlite_stats["wins"]
                conn.close()
        except Exception as sq_err:
            sqlite_stats["error"] = str(sq_err)
        
        # Get learning status
        learning_status = {
            "enabled": True,
            "feature_weights_count": len(feedback.feature_weights),
            "signals_tracked": len(feedback.signal_performance),
            "recent_outcomes_cached": len(feedback.recent_outcomes),
        }
        
        # Top performing features
        top_features = []
        for name, weight in sorted(feedback.feature_weights.items(), key=lambda x: x[1], reverse=True)[:10]:
            top_features.append({"feature": name, "weight": weight})
        
        # Signal performance
        signal_stats = []
        for signal, stats in feedback.signal_performance.items():
            if stats["total"] >= 5:
                acc = stats["correct"] / stats["total"] if stats["total"] > 0 else 0
                signal_stats.append({
                    "signal": signal,
                    "accuracy": f"{acc:.1%}",
                    "total": stats["total"],
                    "correct": stats["correct"]
                })
        signal_stats.sort(key=lambda x: x["total"], reverse=True)
        
        return {
            "ok": True,
            "learning_active": feedback_report.get("learning_status") == "active",
            "data_sources": {
                "postgres_outcomes": postgres_stats,
                "sqlite_feedback_loop": sqlite_stats,
                "memory_cache": len(feedback.recent_outcomes),
            },
            "total_outcomes_processed": feedback_report.get("total_predictions", 0),
            "accuracy_rate": f"{feedback_report.get('accuracy_rate', 0):.1%}",
            "avg_accuracy_pct": f"{feedback_report.get('avg_accuracy_pct', 0):.1f}%",
            "feature_weights": top_features[:5],
            "signal_performance": signal_stats[:5],
            "learning_status": learning_status,
            "feedback_report": feedback_report,
        }
    except Exception as e:
        import traceback
        return {"ok": False, "error": str(e), "traceback": traceback.format_exc()}


# ============================================================================
# LEARNING SYSTEM ENDPOINTS - For reconciliation and dashboard
# ============================================================================

@APP.post("/alerts/reconcile/now")
async def reconcile_predictions_now(request: Request):
    """
    🎯 ON-DEMAND PREDICTION RECONCILIATION
    
    Called by cron-job.org to process predictions that are now 48+ hours old.
    SECURED: Requires X-Cron-Secret header matching CRON_SECRET env var.
    
    Process:
    1. Call the existing outcome_reconciler_v2 to process pending predictions
    2. Compute per-symbol accuracy from the outcomes table
    3. Update ghost_symbol_accuracy table for TOP 10 learning
    
    Returns:
        - reconciler_result: Result from the outcome reconciler
        - symbol_accuracy_updated: How many symbols had their accuracy computed
    """
    import psycopg2
    from datetime import datetime
    
    # Check cron secret for authentication
    cron_secret = os.getenv("CRON_SECRET", "")
    provided_secret = request.headers.get("X-Cron-Secret", "")
    
    # Allow bypass for local testing or if already authenticated via bearer token
    bypass_auth = os.getenv("BYPASS_CRON_AUTH", "false") == "true"
    
    # Also allow if request has valid bearer token (already authenticated)
    auth_header = request.headers.get("Authorization", "")
    has_valid_bearer = auth_header.startswith("Bearer ") and auth_header[7:] == os.getenv("API_SECRET", "ghost-prod-2024")
    
    if not bypass_auth and not has_valid_bearer and cron_secret and provided_secret != cron_secret:
        LOGGER.warning(f"[RECONCILE] Unauthorized reconcile attempt")
        return {"ok": False, "error": "Unauthorized - invalid X-Cron-Secret"}
    
    database_url = os.getenv("DATABASE_URL")
    if not database_url:
        return {"ok": False, "error": "DATABASE_URL not configured"}
    
    try:
        # Step 1: Run the existing outcome reconciler
        reconciler_result = {"skipped": True, "reason": "reconciler not run"}
        try:
            from services.outcome_reconciler_v2 import reconcile_outcomes_v2
            reconciler_result = reconcile_outcomes_v2()
            LOGGER.info(f"[RECONCILE] Outcome reconciler result: {reconciler_result}")
        except Exception as rec_err:
            LOGGER.error(f"[RECONCILE] Reconciler error: {rec_err}")
            reconciler_result = {"error": str(rec_err)}
        
        # Step 2: Compute symbol accuracy from outcomes table
        conn = psycopg2.connect(database_url)
        cur = conn.cursor()
        
        # Create ghost_symbol_accuracy table if it doesn't exist
        cur.execute("""
            CREATE TABLE IF NOT EXISTS ghost_symbol_accuracy (
                symbol VARCHAR(20) PRIMARY KEY,
                total_predictions INTEGER DEFAULT 0,
                correct_predictions INTEGER DEFAULT 0,
                accuracy_pct NUMERIC(5, 2) DEFAULT 0,
                last_updated TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        """)
        conn.commit()
        
        # Check if we're in INVERSE_GHOST mode - FIXED: Use INVERSE_GHOST (not INVERSE_GHOST_MODE) - default to OFF (0)
        inverse_mode = os.getenv("INVERSE_GHOST", "0") == "1"
        
        # Compute per-symbol accuracy from ghost_prediction_outcomes table
        # In INVERSE_GHOST mode, hit_direction=0 (raw wrong) is actually CORRECT
        # because we invert the raw predictions
        if inverse_mode:
            # Inverted accuracy: count when hit_direction=0 as correct
            cur.execute("""
                SELECT 
                    symbol,
                    COUNT(*) as total,
                    SUM(CASE WHEN hit_direction = 0 THEN 1 ELSE 0 END) as correct
                FROM ghost_prediction_outcomes
                WHERE symbol IS NOT NULL
                GROUP BY symbol
                HAVING COUNT(*) >= 1
            """)
        else:
            # Normal mode: hit_direction=1 means correct
            cur.execute("""
                SELECT 
                    symbol,
                    COUNT(*) as total,
                    SUM(CASE WHEN hit_direction = 1 THEN 1 ELSE 0 END) as correct
                FROM ghost_prediction_outcomes
                WHERE symbol IS NOT NULL
                GROUP BY symbol
                HAVING COUNT(*) >= 1
            """)
        
        symbol_stats = cur.fetchall()
        symbols_updated = 0
        
        for stat in symbol_stats:
            symbol, total, correct = stat
            accuracy = (correct / total * 100) if total > 0 else 0
            
            cur.execute("""
                INSERT INTO ghost_symbol_accuracy (symbol, total_predictions, correct_predictions, accuracy_pct, last_updated)
                VALUES (%s, %s, %s, %s, NOW())
                ON CONFLICT (symbol) DO UPDATE SET
                    total_predictions = EXCLUDED.total_predictions,
                    correct_predictions = EXCLUDED.correct_predictions,
                    accuracy_pct = EXCLUDED.accuracy_pct,
                    last_updated = NOW()
            """, (symbol, total, correct, accuracy))
            symbols_updated += 1
        
        conn.commit()
        
        # Get summary stats
        cur.execute("""
            SELECT 
                COUNT(*) as symbols_tracked,
                AVG(accuracy_pct) as avg_accuracy,
                COUNT(CASE WHEN accuracy_pct < 40 AND total_predictions >= 10 THEN 1 END) as excluded_count,
                COUNT(CASE WHEN accuracy_pct >= 70 AND total_predictions >= 10 THEN 1 END) as boosted_count
            FROM ghost_symbol_accuracy
        """)
        summary = cur.fetchone()
        
        # Get lists of excluded and boosted symbols
        cur.execute("""
            SELECT symbol, accuracy_pct, total_predictions
            FROM ghost_symbol_accuracy
            WHERE total_predictions >= 10 AND accuracy_pct < 40
            ORDER BY accuracy_pct ASC
            LIMIT 20
        """)
        excluded = [{"symbol": r[0], "accuracy": float(r[1]), "predictions": r[2]} for r in cur.fetchall()]
        
        cur.execute("""
            SELECT symbol, accuracy_pct, total_predictions
            FROM ghost_symbol_accuracy
            WHERE total_predictions >= 10 AND accuracy_pct >= 70
            ORDER BY accuracy_pct DESC
            LIMIT 20
        """)
        boosted = [{"symbol": r[0], "accuracy": float(r[1]), "predictions": r[2]} for r in cur.fetchall()]
        
        cur.close()
        conn.close()
        
        LOGGER.info(f"[RECONCILE] ✅ Updated accuracy for {symbols_updated} symbols")
        
        return {
            "ok": True,
            "reconciler_result": reconciler_result,
            "symbol_accuracy_updated": symbols_updated,
            "summary": {
                "symbols_tracked": summary[0] if summary else 0,
                "avg_accuracy_pct": float(summary[1]) if summary and summary[1] else 0,
                "excluded_from_top10": summary[2] if summary else 0,
                "boosted_in_top10": summary[3] if summary else 0,
            },
            "excluded_symbols": excluded,
            "boosted_symbols": boosted,
            "timestamp": datetime.utcnow().isoformat()
        }
        
    except Exception as e:
        import traceback
        LOGGER.error(f"[RECONCILE] Error: {e}")
        return {"ok": False, "error": str(e), "traceback": traceback.format_exc()}


@APP.get("/api/learning/dashboard")
async def learning_dashboard():
    """
    🎯 LEARNING DASHBOARD
    
    Returns comprehensive learning metrics including:
    - Overall accuracy (raw and inverted)
    - Per-symbol accuracy table
    - Symbols excluded from TOP 10 (low accuracy)
    - Symbols boosted in TOP 10 (high accuracy)
    - Recent outcomes
    """
    import psycopg2
    from datetime import datetime, timedelta
    
    database_url = os.getenv("DATABASE_URL")
    if not database_url:
        return {"ok": False, "error": "DATABASE_URL not configured"}
    
    try:
        conn = psycopg2.connect(database_url)
        cur = conn.cursor()
        
        # Create ghost_symbol_accuracy table if not exists
        cur.execute("""
            CREATE TABLE IF NOT EXISTS ghost_symbol_accuracy (
                symbol VARCHAR(20) PRIMARY KEY,
                total_predictions INTEGER DEFAULT 0,
                correct_predictions INTEGER DEFAULT 0,
                accuracy_pct NUMERIC(5, 2) DEFAULT 0,
                last_updated TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        """)
        conn.commit()
        
        # Get overall stats from ghost_prediction_outcomes table (the actual reconciled data)
        cur.execute("""
            SELECT 
                COUNT(*) as total,
                SUM(CASE WHEN hit_direction = 1 THEN 1 ELSE 0 END) as correct,
                AVG(CASE WHEN hit_direction = 1 THEN 1.0 ELSE 0.0 END) * 100 as accuracy_pct
            FROM ghost_prediction_outcomes
        """)
        row = cur.fetchone()
        overall_stats = {
            "total_evaluated": row[0] or 0,
            "total_correct": row[1] or 0,
            "raw_accuracy_pct": float(row[2]) if row[2] else 0,
        }
        
        # With INVERSE_GHOST=1, if raw is X%, inverted is 100-X% - FIXED: Use INVERSE_GHOST (not INVERSE_GHOST_MODE) - default to OFF (0)
        inverse_mode = os.getenv("INVERSE_GHOST", "0") == "1"
        if inverse_mode:
            overall_stats["inverted_accuracy_pct"] = 100 - overall_stats["raw_accuracy_pct"]
            overall_stats["mode"] = "INVERSE_GHOST (raw predictions inverted)"
        else:
            overall_stats["inverted_accuracy_pct"] = overall_stats["raw_accuracy_pct"]
            overall_stats["mode"] = "NORMAL"
        
        # Get symbols to exclude (accuracy < 40% with 10+ predictions)
        cur.execute("""
            SELECT symbol, total_predictions, correct_predictions, accuracy_pct
            FROM ghost_symbol_accuracy
            WHERE total_predictions >= 10 AND accuracy_pct < 40
            ORDER BY accuracy_pct ASC
        """)
        excluded_symbols = []
        for row in cur.fetchall():
            excluded_symbols.append({
                "symbol": row[0],
                "total": row[1],
                "correct": row[2],
                "accuracy_pct": float(row[3]) if row[3] else 0,
                "reason": "accuracy < 40%"
            })
        
        # Get symbols to boost (accuracy >= 70% with 10+ predictions)
        cur.execute("""
            SELECT symbol, total_predictions, correct_predictions, accuracy_pct
            FROM ghost_symbol_accuracy
            WHERE total_predictions >= 10 AND accuracy_pct >= 70
            ORDER BY accuracy_pct DESC
        """)
        boosted_symbols = []
        for row in cur.fetchall():
            boosted_symbols.append({
                "symbol": row[0],
                "total": row[1],
                "correct": row[2],
                "accuracy_pct": float(row[3]) if row[3] else 0,
                "boost": "+15% confidence"
            })
        
        # Get all symbol accuracy (top 50 by total predictions)
        cur.execute("""
            SELECT symbol, total_predictions, correct_predictions, accuracy_pct, last_updated
            FROM ghost_symbol_accuracy
            ORDER BY total_predictions DESC
            LIMIT 50
        """)
        all_symbols = []
        for row in cur.fetchall():
            all_symbols.append({
                "symbol": row[0],
                "total": row[1],
                "correct": row[2],
                "accuracy_pct": float(row[3]) if row[3] else 0,
                "last_updated": row[4].isoformat() if row[4] else None
            })
        
        # Get recent outcomes (last 20) from ghost_prediction_outcomes table
        cur.execute("""
            SELECT symbol, predicted_direction, actual_direction, hit_direction, 
                   price_at_prediction, price_at_resolution, realized_move_pct, closed_at
            FROM ghost_prediction_outcomes
            ORDER BY closed_at DESC NULLS LAST
            LIMIT 20
        """)
        recent_outcomes = []
        for row in cur.fetchall():
            # closed_at is a timestamp (could be datetime or float)
            evaluated_at = None
            if row[7]:
                if isinstance(row[7], datetime):
                    evaluated_at = row[7].isoformat()
                elif isinstance(row[7], (int, float)):
                    evaluated_at = datetime.fromtimestamp(row[7]).isoformat()
                else:
                    evaluated_at = str(row[7])
            
            recent_outcomes.append({
                "symbol": row[0],
                "predicted": row[1],
                "actual": row[2],
                "correct": row[3] == 1,
                "entry_price": float(row[4]) if row[4] else 0,
                "exit_price": float(row[5]) if row[5] else 0,
                "change_pct": float(row[6]) if row[6] else 0,
                "evaluated_at": evaluated_at
            })
        
        cur.close()
        conn.close()
        
        # Import learning config from ghost_notifications
        try:
            from core.ghost_notifications import (
                LEARNING_ENABLED, LEARNING_BOOST_ENABLED, LEARNING_EXCLUDE_ENABLED,
                LEARNING_MIN_PREDICTIONS, LEARNING_EXCLUDE_ACCURACY, LEARNING_BOOST_ACCURACY,
                LEARNING_BOOST_AMOUNT, HARDCODED_EXCLUSIONS
            )
            learning_config = {
                "learning_enabled": LEARNING_ENABLED,
                "boost_enabled": LEARNING_BOOST_ENABLED,
                "exclude_enabled": LEARNING_EXCLUDE_ENABLED,
                "min_predictions": LEARNING_MIN_PREDICTIONS,
                "exclude_threshold": LEARNING_EXCLUDE_ACCURACY,
                "boost_threshold": LEARNING_BOOST_ACCURACY,
                "boost_amount": LEARNING_BOOST_AMOUNT,
                "hardcoded_exclusions": list(HARDCODED_EXCLUSIONS.keys()),
                "hardcoded_exclusions_details": HARDCODED_EXCLUSIONS
            }
        except ImportError:
            learning_config = {"error": "Could not import learning config"}
        
        return {
            "ok": True,
            "config": learning_config,
            "overall_accuracy": overall_stats,
            "learning_adjustments": {
                "excluded_from_top10": {
                    "count": len(excluded_symbols),
                    "reason": "accuracy < 40% after 10+ predictions",
                    "symbols": excluded_symbols
                },
                "boosted_in_top10": {
                    "count": len(boosted_symbols),
                    "reason": "accuracy >= 70% after 10+ predictions",
                    "boost_amount": "+15% confidence",
                    "symbols": boosted_symbols
                }
            },
            "symbol_accuracy_top50": all_symbols,
            "recent_outcomes": recent_outcomes,
            "timestamp": datetime.utcnow().isoformat()
        }
        
    except Exception as e:
        import traceback
        return {"ok": False, "error": str(e), "traceback": traceback.format_exc()}


@APP.get("/api/learning/symbol/{symbol}")
async def learning_symbol_accuracy(symbol: str):
    """
    Get detailed accuracy information for a specific symbol.
    """
    import psycopg2
    from datetime import datetime
    
    database_url = os.getenv("DATABASE_URL")
    if not database_url:
        return {"ok": False, "error": "DATABASE_URL not configured"}
    
    try:
        conn = psycopg2.connect(database_url)
        cur = conn.cursor()
        
        # Get symbol accuracy from ghost_symbol_accuracy table
        cur.execute("""
            SELECT symbol, total_predictions, correct_predictions, accuracy_pct, last_updated
            FROM ghost_symbol_accuracy
            WHERE symbol = %s
        """, (symbol.upper(),))
        
        row = cur.fetchone()
        if not row:
            # Try to compute from ghost_prediction_outcomes table directly
            cur.execute("""
                SELECT 
                    symbol,
                    COUNT(*) as total,
                    SUM(CASE WHEN hit_direction = 1 THEN 1 ELSE 0 END) as correct
                FROM ghost_prediction_outcomes
                WHERE symbol = %s
                GROUP BY symbol
            """, (symbol.upper(),))
            outcome_row = cur.fetchone()
            if not outcome_row:
                return {"ok": False, "error": f"No accuracy data for {symbol}"}
            
            symbol_data = {
                "symbol": outcome_row[0],
                "total_predictions": outcome_row[1],
                "correct_predictions": outcome_row[2],
                "accuracy_pct": (outcome_row[2] / outcome_row[1] * 100) if outcome_row[1] > 0 else 0,
                "last_updated": None,
                "source": "computed_from_ghost_prediction_outcomes"
            }
        else:
            symbol_data = {
                "symbol": row[0],
                "total_predictions": row[1],
                "correct_predictions": row[2],
                "accuracy_pct": float(row[3]) if row[3] else 0,
                "last_updated": row[4].isoformat() if row[4] else None,
                "source": "ghost_symbol_accuracy"
            }
        
        # Determine status
        if symbol_data["total_predictions"] < 10:
            symbol_data["status"] = "insufficient_data"
            symbol_data["learning_action"] = "none"
        elif symbol_data["accuracy_pct"] < 40:
            symbol_data["status"] = "low_accuracy"
            symbol_data["learning_action"] = "EXCLUDED from TOP 10"
        elif symbol_data["accuracy_pct"] >= 70:
            symbol_data["status"] = "high_accuracy"
            symbol_data["learning_action"] = "BOOSTED +15% confidence"
        else:
            symbol_data["status"] = "normal"
            symbol_data["learning_action"] = "none"
        
        # Get recent outcomes for this symbol from ghost_prediction_outcomes table
        cur.execute("""
            SELECT predicted_direction, actual_direction, hit_direction, 
                   price_at_prediction, price_at_resolution, realized_move_pct, closed_at
            FROM ghost_prediction_outcomes
            WHERE symbol = %s
            ORDER BY closed_at DESC NULLS LAST
            LIMIT 10
        """, (symbol.upper(),))
        
        recent = []
        for r in cur.fetchall():
            # closed_at is a timestamp (could be datetime or float)
            evaluated_at = None
            if r[6]:
                if isinstance(r[6], datetime):
                    evaluated_at = r[6].isoformat()
                elif isinstance(r[6], (int, float)):
                    evaluated_at = datetime.fromtimestamp(r[6]).isoformat()
                else:
                    evaluated_at = str(r[6])
            
            recent.append({
                "predicted": r[0],
                "actual": r[1],
                "correct": r[2] == 1,
                "entry": float(r[3]) if r[3] else 0,
                "exit": float(r[4]) if r[4] else 0,
                "change_pct": float(r[5]) if r[5] else 0,
                "evaluated_at": evaluated_at
            })
        
        symbol_data["recent_outcomes"] = recent
        
        cur.close()
        conn.close()
        
        return {"ok": True, **symbol_data}
        
    except Exception as e:
        import traceback
        return {"ok": False, "error": str(e), "traceback": traceback.format_exc()}


