@APP.get("/api/v3/accuracy/metrics")
async def api_v3_accuracy_metrics(days: int = 30, symbol: str | None = None):
    """Directional hit-rate + MAPE from PredictionStore outcomes (facts-only)."""
    try:
        from core.prediction_store import get_prediction_store

        store = get_prediction_store()
        since_ts = time.time() - max(1, int(days)) * 86400

        symbols: list[str]
        if symbol:
            symbols = [symbol.upper().strip()]
        else:
            # Keep it bounded: compute for symbols we actively track.
            symbols = sorted(set((STOCK_SYMBOLS or []) + (CRYPTO_SYMBOLS or [])))

        total_n = 0
        total_hits = 0
        map_vals: list[float] = []
        band_hits = 0

        per_symbol: dict[str, dict[str, Any]] = {}
        for sym in symbols:
            rows = store.get_predictions_with_outcomes_since(sym, since_ts)
            n = len(rows)
            if n <= 0:
                continue
            hits = 0
            sym_map_vals: list[float] = []
            sym_band_hits = 0
            for r in rows:
                try:
                    hits += 1 if int(r.get("hit_direction") or 0) == 1 else 0
                except Exception:
                    pass
                try:
                    mv = r.get("map")
                    if mv is not None:
                        mvf = float(mv)
                        sym_map_vals.append(mvf)
                        # Secondary tolerance band: MAPE <= 1.0% (default band).
                        if mvf <= 1.0:
                            sym_band_hits += 1
                except Exception:
                    pass

            total_n += n
            total_hits += hits
            map_vals.extend(sym_map_vals)
            band_hits += sym_band_hits

            per_symbol[sym] = {
                "n": n,
                "hit_rate": (hits / n) if n else None,
                "mape_pct": (sum(sym_map_vals) / len(sym_map_vals)) if sym_map_vals else None,
                "within_1pct_band_rate": (sym_band_hits / len(sym_map_vals)) if sym_map_vals else None,
            }

        hit_rate = (total_hits / total_n) if total_n else None
        mape = (sum(map_vals) / len(map_vals)) if map_vals else None
        band_rate = (band_hits / len(map_vals)) if map_vals else None

        return {
            "ok": True,
            "window_days": int(days),
            "since_ts": since_ts,
            "overall": {
                "n": total_n,
                "directional_hit_rate": hit_rate,
                "mape_pct": mape,
                "within_1pct_band_rate": band_rate,
                "gate_min_hit_rate": 0.70,
                "band_tolerance_pct": 1.0,
            },
            "per_symbol": per_symbol,
        }
    except Exception as e:
        return {"ok": False, "error": str(e)[:200]}


@APP.post("/api/v3/regression/telegram-test")
async def api_v3_regression_telegram_test(request: Request):
    """Send a single controlled Telegram message for regression auditing.

    Guardrails:
    - requires REGRESSION_ALLOW_TELEGRAM_TEST=1
    - requires X-Regression-Key header matching REGRESSION_KEY
    """
    allow = _is_truthy(os.getenv("REGRESSION_ALLOW_TELEGRAM_TEST", "0"))
    key_required = (os.getenv("REGRESSION_KEY") or "").strip()
    key_got = (request.headers.get("x-regression-key") or "").strip()

    if not allow:
        raise HTTPException(status_code=403, detail="telegram_regression_test_disabled")
    if not key_required or key_got != key_required:
        raise HTTPException(status_code=403, detail="invalid_regression_key")
    if not TELEGRAM_BOT_TOKEN or not TELEGRAM_CHAT_ID:
        return {"ok": False, "error": "telegram_not_configured"}

    # Exact template required by regression spec.
    ts = datetime.now(UTC).isoformat()
    msg = (
        "🔍 GHOST PROTOCOL — REGRESSION TEST\n\n"
        "Status: TELEGRAM PIPELINE VERIFIED\n"
        "Environment: PRODUCTION (Railway)\n"
        f"Timestamp (UTC): {ts}\n\n"
        "This is a controlled system test.\n"
        "• No trade signal generated\n"
        "• No capital at risk\n"
        "• No prediction executed\n\n"
        "If you received this message, Ghost Protocol can successfully send Telegram notifications end-to-end."
    )

    ok_all, deliveries = await asyncio.to_thread(send_telegram_detailed, msg)
    return {"ok": bool(ok_all), "deliveries": deliveries}




